"use client";

/*
 * Progressive blur technique informed by:
 * - Skiper UI Progressive Blur: https://skiper-ui.com/v1/skiper41
 * - Kenneth Nym, "progressive blur in css":
 *   https://kennethnym.com/blog/progressive-blur-in-css/
 *
 * Skiper UI credits Devouring Details as the inspiration for its version:
 * https://devouringdetails.com/
 *
 * This implementation uses independently generated, overlapping mask bands and
 * exponential blur steps. It does not copy either reference's source code.
 */

import { forwardRef, type CSSProperties, type HTMLAttributes } from "react";

export type ProgressiveBlurPosition = "top" | "bottom";

export interface ProgressiveBlurStyle extends CSSProperties {
  /** Surface color used by the edge fade. */
  "--bui-progressive-blur-surface"?: string;
}

export interface ProgressiveBlurProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  "children" | "style" | "tabIndex"
> {
  /** Edge where the blur becomes strongest. */
  position?: ProgressiveBlurPosition;
  /** Size of the blur region in pixels or any CSS length. */
  height?: number | string;
  /** Strongest blur radius in pixels. */
  blurAmount?: number;
  /** Number of overlapping blur bands. Use 1 for the lightweight variant. */
  layers?: number;
  /** Color blended into the strongest edge to hide backdrop-filter artifacts. */
  backgroundColor?: string;
  /** Renders relative to the viewport instead of the nearest positioned ancestor. */
  fixed?: boolean;
  /** Shows the surface-color fade above the blur bands. */
  fade?: boolean;
  /** Native styles plus the typed surface-color variable. */
  style?: ProgressiveBlurStyle;
}

function joinClassNames(...parts: Array<string | false | null | undefined>) {
  return parts.filter(Boolean).join(" ");
}

function clamp(value: number, minimum: number, maximum: number) {
  return Math.min(Math.max(value, minimum), maximum);
}

function toCssLength(value: number | string) {
  return typeof value === "number" ? `${Math.max(0, value)}px` : value;
}

function maskForLayer(index: number, total: number, direction: "to top" | "to bottom") {
  if (total === 1) {
    return `linear-gradient(${direction}, transparent 0%, #000 65%, #000 100%)`;
  }

  // Each band overlaps its neighbors. The final band stays opaque at the edge,
  // while intermediate bands fade out before the next blur strength takes over.
  const start = clamp(((index - 0.75) / total) * 100, 0, 100);
  const solidStart = clamp(((index + 0.25) / total) * 100, 0, 100);
  const solidEnd = clamp(((index + 1.5) / total) * 100, 0, 100);
  const end = clamp(((index + 2.25) / total) * 100, 0, 100);
  const stops = [`transparent ${start}%`, `#000 ${solidStart}%`, `#000 ${solidEnd}%`];

  if (end < 100) stops.push(`transparent ${end}%`);
  else stops.push("#000 100%");

  return `linear-gradient(${direction}, ${stops.join(", ")})`;
}

export const ProgressiveBlur = forwardRef<HTMLDivElement, ProgressiveBlurProps>(
  function ProgressiveBlur(
    {
      position = "bottom",
      height = 160,
      blurAmount = 10,
      layers = 5,
      backgroundColor = "var(--background)",
      fixed = false,
      fade = true,
      className,
      style,
      ...props
    },
    ref,
  ) {
    const layerCount = Number.isFinite(layers) ? clamp(Math.round(layers), 1, 8) : 5;
    const maximumBlur = Number.isFinite(blurAmount) ? clamp(blurAmount, 0, 64) : 10;
    const direction = position === "top" ? "to top" : "to bottom";
    const edgeStyles =
      position === "top" ? { top: 0, right: 0, left: 0 } : { right: 0, bottom: 0, left: 0 };

    return (
      <div
        {...props}
        ref={ref}
        aria-hidden="true"
        tabIndex={-1}
        data-progressive-blur=""
        data-position={position}
        data-layers={layerCount}
        className={joinClassNames("bui-progressive-blur", className)}
        style={{
          "--bui-progressive-blur-surface": backgroundColor,
          position: fixed ? "fixed" : "absolute",
          width: "100%",
          height: toCssLength(height),
          overflow: "hidden",
          isolation: "isolate",
          userSelect: "none",
          ...edgeStyles,
          ...style,
          pointerEvents: "none",
        }}
      >
        {Array.from({ length: layerCount }, (_, index) => {
          const divisor = 2 ** (layerCount - index - 1);
          const blur = layerCount === 1 ? maximumBlur : maximumBlur / divisor;
          const maskImage = maskForLayer(index, layerCount, direction);

          return (
            <span
              key={index}
              data-progressive-blur-layer={index + 1}
              style={{
                position: "absolute",
                inset: 0,
                zIndex: index,
                WebkitBackdropFilter: `blur(${blur}px)`,
                backdropFilter: `blur(${blur}px)`,
                WebkitMaskImage: maskImage,
                maskImage,
              }}
            />
          );
        })}

        {fade ? (
          <span
            data-progressive-blur-fade=""
            style={{
              position: "absolute",
              inset: 0,
              zIndex: layerCount,
              backgroundImage: `linear-gradient(${direction}, transparent 0%, var(--bui-progressive-blur-surface) 100%)`,
            }}
          />
        ) : null}
      </div>
    );
  },
);

ProgressiveBlur.displayName = "ProgressiveBlur";
